import { ChangeDetectionStrategy, Component } from '@angular/core';
import { SemiFinishedService } from '../../services/semi-finished-service';
import { FormGroup, FormBuilder, Validators, ReactiveFormsModule } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-edit-semi-finished',
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './edit-semi-finished.html',
  styleUrl: './edit-semi-finished.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class EditSemiFinished {
semiFinishedForm! : FormGroup;
semiFinishedId! : number;
isLoading = true;

constructor(
    private fb: FormBuilder,
    private service: SemiFinishedService,
    private route: ActivatedRoute,
    private router: Router
  ) {}

    ngOnInit(): void {
    this.semiFinishedForm = this.fb.group({
      name: ['', Validators.required],
      price: [''],
    });
   const id = Number(this.route.snapshot.paramMap.get('id'));
    if (id) {
      this.semiFinishedId = id;
      this.service.getProductByID(id).subscribe(product => {
        this.semiFinishedForm.patchValue(product); 
        this.isLoading = false;
      });
    } else {
      this.isLoading = false;
    }
    }
    onCancel(){
    this.resetForm();
    this.router.navigate(['/semi-finished']);
  }
   onSubmit() {
  if (this.semiFinishedForm.invalid) 
    return;

   const dto = {
    ...this.semiFinishedForm.value,
   }

  console.log("Submitting semi-finished:", dto);

  this.service.updateProduct(this.semiFinishedId, dto).subscribe({
    next: () => {
      alert('✅ Product updated successfully');
      this.resetForm();
    },
    error: (err) => {
      console.error('❌ Upload failed', err);
      alert(err.error?.message || 'Upload failed. Please try again.');
    }
  });

  this.router.navigate(['/semi-finished'])
}


  private resetForm() {
    this.semiFinishedForm.reset();
  }
}

